mapper.select:
select from edu_class c left join edu_campus cp on cp.id = c.campus_id left join sys_user u on u.id = c.head_teacher_id left join edu_course crs on crs.id = c.course_id
and ( cast(c.class_term as char) like concat('%', #{keyword}, '%') or ifnull(cp.campus_name, '') like concat('%', #{keyword}, '%') or ifnull(u.real_name, '') like concat('%', #{keyword}, '%') or ifnull(u.nickname, '') like concat('%', #{keyword}, '%') or ifnull(u.username, '') like concat('%', #{keyword}, '%') or ifnull(crs.course_name, '') like concat('%', #{keyword}, '%') )
and c.class_status = #{classStatus}
and c.campus_id = #{campusId}
and c.head_teacher_id = #{headTeacherId}
and c.course_id = #{courseId}
order by c.id desc
